          solderMaskAndPasteMaskExpansion: plain(await state(primitive, "getState_SolderMaskAndPasteMaskExpansion"), "pad mask expansion"),
          heatWelding: plain(await state(primitive, "getState_HeatWelding"), "pad heat welding"),
